const names = ['kim','lee','park','choi','jung'];
const rnd = (n) => Math.floor(Math.random() * n);
let fails = 0; const eq = (a, b, label) => { if (JSON.stringify(a) !== JSON.stringify(b)) { fails++; console.log('FAIL', label, a, b); } };
const row = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
