const tl = [["kim",4],["kim",56],["choi",75],["kim",24],["lee",62],["kim",34]];
eq(m.toLookup([]), refFromPairs([]), 'tl-empty'); eq(m.toLookup(tl), refFromPairs(tl), 'tl-ex2');
// random in-range
for (let t = 0; t < 20000; t++) {
  const r = row(); eq(m.publicFields(r), refPick(r, ['id','name']), 'pf');
  const rows = Array.from({length: rnd(13)}, row); eq(m.totalAge(rows), refSumBy(rows), 'ta');
  const ps = Array.from({length: rnd(9)}, () => [names[rnd(5)], rnd(100)]); eq(m.toLookup(ps), refFromPairs(ps), 'tl');
}
console.log('exports:', Object.keys(m).sort().join(','));
console.log(fails === 0 ? 'ALL MATCH (20000 random + examples)' : `FAILURES: ${fails}`);
EOF
node "$S/check.mjs"

